import { FINANCE_TODAY, allObligations, can, cashExpected, computeSummary, eligibleAttenances, financeActor, financeStore, obligationSaldo, pendingGroups, resolvePeriod, type FinancePeriod, type MediaLine, type MoneyMovement } from "../state/financeCore"
import { addDocument, adjustSale, applyAdvance, closeCash, collect, correctMovement, countCash, createAdvance, createCommercialObligation, createExpense, createOtherReceivable, createRecurringRule, createSale, deliverThirdPartyFunds, generateRecurringInstance, handoffCash, inspectUnknown, manualCashMovement, openCash, pay, refund, registerMinimalClient, requestApproval, resolveApproval, resolveDepositPolicy, transferFunds, upsertCategory, verifyExternalPayment, withdraw, type FinanceResult } from "../state/financeOps"
